// Helper: Call Groq API as Primary with Gemini Fallback
async function callLLM(systemPrompt: string, userPrompt: string, jsonMode = true): Promise<any> {
  const groqKey = process.env.GROQ_API_KEY;
  if (groqKey) {
    try {
      const response = await fetch("https://api.groq.com/openai/v1/chat/completions", {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${groqKey}`,
          "Content-Type": "application/json"
        },
        body: JSON.stringify({
          model: "llama-3.3-70b-versatile",
          messages: [
            { role: "system", content: systemPrompt },
            { role: "user", content: userPrompt }
          ],
          response_format: jsonMode ? { type: "json_object" } : { type: "text" },
          temperature: 0.2
        })
      });

      if (response.ok) {
        const data = await response.json();
        const content = data.choices?.[0]?.message?.content;
        if (content) {
          return jsonMode ? JSON.parse(content) : content;
        }
      } else {
        const errText = await response.text();
        console.warn("Groq API error, falling back to Gemini:", errText);
      }
    } catch (err) {
      console.warn("Groq API exception, falling back to Gemini:", err);
    }
  }

  // Fallback to Gemini
  const geminiResponse = await ai.models.generateContent({
    model: "gemini-3.6-flash",
    contents: `${systemPrompt}\n\n${userPrompt}`,
    config: jsonMode ? { responseMimeType: "application/json" } : {}
  });

  const text = geminiResponse.text || "{}";
  return jsonMode ? JSON.parse(text) : text;
}

